options.customCss:
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@700;900&family=Fira+Code:wght@400;600&family=Chakra+Petch:wght@500&display=swap');

:root {
  /* Cores Promovaweb - Padrão Real */
  --chat--color-primary: #00D9A5;
  --chat--color-primary-shade-50: #00BF8F;
  --chat--color-primary-shade-100: #00A67A;
  --chat--color-secondary: #00E5CC;
  --chat--color-secondary-shade-50: #00CCB3;
  --chat--color-accent: #1E3A5F;
  --chat--color-accent-dark: #0A4A52;
  --chat--color-white: #FFFFFF;
  --chat--color-light: #E0F7F4;
  --chat--color-dark: #0A1628;
  --chat--color-dark-lighter: #162841;
  --chat--color-disabled: #4A5568;
  --chat--color-typing: var(--chat--color-primary);
  --chat--border-color-glow: rgba(0, 217, 165, 0.5);
  --chat--spacing: 1rem;
  --chat--border-radius: 1.5rem;
  --chat--font-family: 'Fira Code', 'Chakra Petch', sans-serif;
  --chat--font-family-headings: 'Orbitron', sans-serif;
  --chat--transition-duration: 0.4s;
  --chat--window--width: 480px;
  --chat--window--height: 85vh;
  --chat--window--bottom: 2rem;
  --chat--window--right: 2rem;
  --chat--window--z-index: 9999;
  --chat--window--border: 2px solid transparent;
  --chat--window--border-radius: var(--chat--border-radius);
  --chat--window--margin-bottom: var(--chat--spacing);
  --chat--body--background: #0A1628;
  --chat--footer--background: rgba(10, 22, 40, 0.9);
  --chat--header--background: linear-gradient(135deg, #0A4A52 0%, #1E3A5F 50%, #00D9A5 100%);
  --chat--header--color: var(--chat--color-white);
  --chat--heading--font-size: 1.8em;
  --chat--subtitle--font-size: 0.9em;
  --chat--header--border-bottom: 1px solid var(--chat--border-color-glow);
  --chat--message--font-size: 1rem;
  --chat--message--padding: 1rem 1.5rem;
  --chat--message--border-radius: 1.2rem;
  --chat--message-line-height: 1.6;
  --chat--message--margin-bottom: 1rem;
  --chat--message--bot--background: rgba(30, 58, 95, 0.6);
  --chat--message--bot--color: var(--chat--color-light);
  --chat--message--user--background: linear-gradient(135deg, #00D9A5, #00E5CC);
  --chat--message--user--color: #0A1628;
  --chat--messages-list--padding: 1.5rem;
  --chat--input--background: rgba(10, 22, 40, 0.6);
  --chat--input--text-color: var(--chat--color-white);
  --chat--input--border-radius: 1rem;
  --chat--input--padding: 1rem;
  --chat--textarea--height: 55px;
  --chat--button--background: linear-gradient(135deg, var(--chat--color-primary), var(--chat--color-secondary));
  --chat--button--color: var(--chat--color-dark);
  --chat--button--border-radius: 1rem;
  --chat--button--hover--background: linear-gradient(135deg, var(--chat--color-secondary), var(--chat--color-primary));
  --chat--input--send--button--color: var(--chat--color-primary);
  --chat--input--send--button--color-hover: var(--chat--color-secondary);
  --chat--toggle--size: 70px;
  --chat--toggle--border-radius: 50%;
  --chat--toggle--background: linear-gradient(145deg, var(--chat--color-primary), var(--chat--color-secondary));
  --chat--toggle--hover--background: linear-gradient(145deg, var(--chat--color-secondary), var(--chat--color-primary));
  --chat--toggle--color: var(--chat--color-dark);
}

/* ===== CHAT WINDOW - ULTRA ENHANCED ===== */
.chat-window {
  border-radius: var(--chat--window--border-radius);
  overflow: hidden;
  background: 
    radial-gradient(circle at 10% 20%, rgba(0, 217, 165, 0.03) 0%, transparent 50%),
    radial-gradient(circle at 90% 80%, rgba(0, 229, 204, 0.03) 0%, transparent 50%),
    radial-gradient(circle at 50% 50%, rgba(30, 58, 95, 0.02) 0%, transparent 50%),
    var(--chat--body--background);
  animation: 
    fadeInGlow 1.2s ease-out forwards,
    aurora-wave 30s ease-in-out infinite,
    nebula-drift 60s linear infinite;
  position: relative;
  box-shadow: 
    0 0 100px rgba(0, 217, 165, 0.3), 
    0 0 120px rgba(0, 229, 204, 0.2),
    0 0 80px rgba(30, 58, 95, 0.2),
    0 0 150px rgba(0, 217, 165, 0.15),
    0 0 200px rgba(0, 229, 204, 0.1),
    inset 0 0 100px rgba(0, 217, 165, 0.02);
  display: flex;
  flex-direction: column;
  transform-style: preserve-3d;
  perspective: 1000px;
}

/* Rotating Border Glow */
.chat-window::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: 
    conic-gradient(
      transparent, 
      rgba(0, 217, 165, 0.4), 
      transparent 30%,
      rgba(0, 229, 204, 0.3),
      transparent 60%,
      rgba(30, 58, 95, 0.2),
      transparent 90%
    );
  animation: 
    rotate-border 8s linear infinite,
    electric-pulse 6s ease-in-out infinite,
    plasma-flow 12s linear infinite;
  z-index: 1;
  filter: blur(3px) brightness(1.1);
  mix-blend-mode: screen;
}

/* Grid Background + Parallax + Stars */
.chat-window::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: 
    radial-gradient(2px 2px at 20% 30%, rgba(0, 217, 165, 0.15), transparent),
    radial-gradient(2px 2px at 60% 70%, rgba(0, 229, 204, 0.2), transparent),
    radial-gradient(1px 1px at 50% 50%, rgba(255, 255, 255, 0.1), transparent),
    radial-gradient(1px 1px at 80% 10%, rgba(0, 217, 165, 0.2), transparent),
    radial-gradient(2px 2px at 90% 60%, rgba(0, 229, 204, 0.1), transparent),
    radial-gradient(1px 1px at 15% 80%, rgba(30, 58, 95, 0.15), transparent),
    repeating-linear-gradient(0deg, rgba(0, 217, 165, 0.03), rgba(0, 217, 165, 0.03) 1px, transparent 1px, transparent 20px), 
    repeating-linear-gradient(90deg, rgba(0, 217, 165, 0.03), rgba(0, 217, 165, 0.03) 1px, transparent 1px, transparent 20px);
  background-size: 
    200% 200%, 200% 200%, 200% 200%, 200% 200%, 200% 200%, 200% 200%,
    100% 100%, 100% 100%;
  animation: 
    starfield-twinkle 8s ease-in-out infinite,
    cosmic-drift 80s linear infinite;
  z-index: 0;
  opacity: 0.4;
  mix-blend-mode: overlay;
  pointer-events: none;
}

.chat-window {
  overflow: visible;
}

.chat-window > *:not(.chat-particle) {
  position: relative;
  z-index: 2;
}

/* ===== CHAT HEADER - MEGA ENHANCED ===== */
.chat-header {
  font-family: var(--chat--font-family-headings);
  text-shadow: 
    0 0 8px var(--chat--color-primary), 
    0 0 12px var(--chat--color-primary), 
    0 0 20px rgba(0, 217, 165, 0.6),
    0 0 30px rgba(0, 229, 204, 0.4),
    0 0 5px rgba(255, 255, 255, 0.8);
  position: relative;
  background: 
    linear-gradient(135deg, rgba(0, 217, 165, 0.05), transparent 50%),
    linear-gradient(225deg, rgba(0, 229, 204, 0.05), transparent 50%),
    var(--chat--header--background);
  color: var(--chat--header--color);
  padding: 1.5rem;
  border-bottom: var(--chat--header--border-bottom);
  text-align: center;
  letter-spacing: 3px;
  animation: 
    neon-flicker 8s infinite alternate, 
    header-glitch 15s infinite,
    breathing 12s ease-in-out infinite;
  z-index: 2;
  border-top-left-radius: var(--chat--window--border-radius);
  border-top-right-radius: var(--chat--window--border-radius);
  overflow: hidden;
  filter: drop-shadow(0 0 10px rgba(0, 217, 165, 0.3));
}

/* Scanline + CRT Effect */
.chat-header::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 200%;
  background-image: 
    linear-gradient(0deg, transparent 50%, rgba(10, 22, 40, 0.3) 50%),
    repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0, 0, 0, 0.1) 2px, rgba(0, 0, 0, 0.1) 4px);
  background-size: 100% 6px, 100% 4px;
  opacity: 0.15;
  animation: 
    scanline 12s linear infinite,
    vhs-tracking 4s steps(1) infinite;
  pointer-events: none;
  mix-blend-mode: multiply;
}

/* Holographic Shimmer + Lens Flare */
.chat-header::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: 
    radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.2) 0%, transparent 50%),
    linear-gradient(45deg, transparent 30%, rgba(255, 255, 255, 0.08) 50%, transparent 70%),
    linear-gradient(135deg, rgba(0, 217, 165, 0.05), rgba(0, 229, 204, 0.05), rgba(30, 58, 95, 0.05));
  animation: 
    holographic-shimmer 6s linear infinite,
    lens-flare 12s ease-in-out infinite;
  pointer-events: none;
  mix-blend-mode: overlay;
}

/* ===== MESSAGES LIST - ULTRA ENHANCED ===== */
.chat-messages-list {
  flex-grow: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: var(--chat--messages-list--padding);
  z-index: 2;
  position: relative;
  background: 
    radial-gradient(ellipse at top, rgba(0, 217, 165, 0.01), transparent),
    radial-gradient(ellipse at bottom, rgba(0, 229, 204, 0.01), transparent);
  animation: ambient-pulse 15s ease-in-out infinite;
}

/* Data Stream + Binary */
.chat-messages-list::before {
  content: '01001010 11010110 00110101 10101011 01110010 00011100 11001101 10010110';
  position: absolute;
  top: 0;
  left: -5px;
  width: 5px;
  height: 100%;
  font-size: 8px;
  color: var(--chat--color-primary);
  opacity: 0.15;
  writing-mode: vertical-rl;
  animation: 
    data-stream 20s linear infinite,
    matrix-rain 30s linear infinite,
    code-flicker 6s steps(1) infinite;
  letter-spacing: 2px;
  overflow: hidden;
  pointer-events: none;
  text-shadow: 0 0 5px currentColor;
}

.chat-messages-list::after {
  content: '11010110 01001010 10101011 00110101 00011100 01110010 10010110 11001101';
  position: absolute;
  top: 0;
  right: -5px;
  width: 5px;
  height: 100%;
  font-size: 8px;
  color: var(--chat--color-secondary);
  opacity: 0.15;
  writing-mode: vertical-rl;
  animation: 
    data-stream 24s linear infinite reverse,
    matrix-rain 36s linear infinite reverse,
    code-flicker 8s steps(1) infinite;
  letter-spacing: 2px;
  overflow: hidden;
  pointer-events: none;
  text-shadow: 0 0 5px currentColor;
}

/* ===== CHAT MESSAGE - MEGA ENHANCED ===== */
.chat-message {
  backdrop-filter: blur(10px) saturate(120%) brightness(1.05);
  -webkit-backdrop-filter: blur(10px) saturate(120%) brightness(1.05);
  max-width: 85%;
  transition: all var(--chat--transition-duration) cubic-bezier(0.165, 0.84, 0.44, 1);
  animation: 
    slideUpFade 0.7s ease-out forwards, 
    message-materialize 0.8s ease-out,
    message-float 8s ease-in-out infinite,
    subtle-glow 6s ease-in-out infinite;
  opacity: 0;
  transform: translateY(20px);
  animation-fill-mode: forwards;
  position: relative;
  filter: 
    drop-shadow(0 4px 20px rgba(0, 0, 0, 0.4))
    drop-shadow(0 0 10px rgba(0, 217, 165, 0.1));
}

.chat-messages-list .chat-message:nth-child(1) { animation-delay: 0.1s; }
.chat-messages-list .chat-message:nth-child(2) { animation-delay: 0.2s; }
.chat-messages-list .chat-message:nth-child(3) { animation-delay: 0.3s; }
.chat-messages-list .chat-message:nth-child(4) { animation-delay: 0.4s; }
.chat-messages-list .chat-message:nth-child(n+5) { animation-delay: 0.5s; }

.chat-message:hover {
  transform: translateY(-5px) scale(1.02) perspective(1000px) rotateX(2deg);
  filter: 
    brightness(1.2) 
    drop-shadow(0 8px 30px rgba(0, 217, 165, 0.3))
    drop-shadow(0 0 20px rgba(0, 229, 204, 0.2));
  z-index: 10;
  animation: 
    hover-pulse 1.2s ease-out,
    hover-shimmer 4s linear infinite;
}

/* ===== USER MESSAGE - ULTRA ENHANCED ===== */
.chat-message-user {
  background: 
    radial-gradient(circle at top right, rgba(255, 255, 255, 0.1), transparent),
    var(--chat--message--user--background);
  color: var(--chat--message--user--color);
  border-radius: 1.2rem 1.2rem 0.2rem 1.2rem;
  box-shadow: 
    0 0 25px rgba(0, 217, 165, 0.3),
    0 0 15px rgba(0, 229, 204, 0.2),
    0 0 35px rgba(30, 58, 95, 0.15),
    inset 0 0 20px rgba(255, 255, 255, 0.1),
    inset -2px -2px 10px rgba(0, 0, 0, 0.2);
  animation: 
    user-message-pulse 5s infinite, 
    chromatic-aberration 6s infinite,
    energy-flow 8s linear infinite,
    diamond-sparkle 6s ease-in-out infinite;
  position: relative;
  overflow: hidden;
  font-weight: 500;
}

/* Liquid Edge + Plasma */
.chat-message-user::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: 
    radial-gradient(circle, rgba(255, 255, 255, 0.2) 0%, transparent 50%),
    radial-gradient(ellipse at 30% 30%, rgba(0, 229, 204, 0.1), transparent),
    radial-gradient(ellipse at 70% 70%, rgba(0, 217, 165, 0.1), transparent);
  animation: 
    liquid-motion 8s ease-in-out infinite,
    plasma-morph 12s ease-in-out infinite,
    energy-rotation 16s linear infinite;
  pointer-events: none;
  mix-blend-mode: overlay;
}

/* Iridescent + Prism */
.chat-message-user::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: 
    linear-gradient(90deg,
      transparent,
      rgba(255, 255, 255, 0.2),
      rgba(0, 229, 204, 0.15),
      rgba(0, 217, 165, 0.15),
      transparent
    );
  animation: 
    iridescent-sweep 6s linear infinite,
    prism-refraction 10s ease-in-out infinite;
  pointer-events: none;
  mix-blend-mode: screen;
}

/* ===== BOT MESSAGE - ULTRA ENHANCED ===== */
.chat-message-bot {
  background: 
    linear-gradient(135deg, rgba(0, 217, 165, 0.03), transparent),
    var(--chat--message--bot--background);
  color: var(--chat--message--bot--color);
  border: 1px solid var(--chat--border-color-glow);
  border-radius: 1.2rem 1.2rem 1.2rem 0.2rem;
  box-shadow: 
    0 4px 30px rgba(0, 0, 0, 0.4),
    0 0 20px rgba(0, 217, 165, 0.15),
    0 0 30px rgba(0, 229, 204, 0.1),
    inset 0 0 30px rgba(0, 217, 165, 0.03),
    inset 0 0 20px rgba(0, 229, 204, 0.02);
  position: relative;
  overflow: hidden;
  animation: 
    bot-message-glow 6s infinite,
    hologram-flicker 10s steps(20) infinite,
    quantum-fluctuation 8s ease-in-out infinite;
}

/* Glass Shine + Caustics */
.chat-message-bot::after {
  content: '';
  position: absolute;
  top: -50%;
  left: -100%;
  width: 200%;
  height: 200%;
  background: 
    linear-gradient(110deg, 
      transparent 40%, 
      rgba(255, 255, 255, 0.12) 45%,
      rgba(0, 217, 165, 0.15) 50%,
      rgba(255, 255, 255, 0.12) 55%,
      transparent 60%
    ),
    radial-gradient(circle at 50% 0%, rgba(255, 255, 255, 0.08), transparent 70%);
  transform: rotate(25deg);
  animation: 
    glass-shine 10s infinite,
    caustics-flow 16s ease-in-out infinite,
    light-rays 12s linear infinite;
  mix-blend-mode: overlay;
}

/* Hexagon + Circuit */
.chat-message-bot::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: 
    repeating-linear-gradient(0deg, transparent, transparent 10px, rgba(0, 217, 165, 0.02) 10px, rgba(0, 217, 165, 0.02) 11px),
    repeating-linear-gradient(60deg, transparent, transparent 10px, rgba(0, 229, 204, 0.02) 10px, rgba(0, 229, 204, 0.02) 11px),
    repeating-linear-gradient(120deg, transparent, transparent 10px, rgba(30, 58, 95, 0.02) 10px, rgba(30, 58, 95, 0.02) 11px),
    radial-gradient(circle at 20% 20%, rgba(0, 217, 165, 0.03) 1px, transparent 1px),
    radial-gradient(circle at 80% 80%, rgba(0, 229, 204, 0.03) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 100% 100%, 20px 20px, 20px 20px;
  opacity: 0.4;
  pointer-events: none;
  animation: 
    circuit-pulse 8s ease-in-out infinite,
    neural-fire 6s steps(10) infinite;
}

/* ===== TYPING INDICATOR - MEGA ENHANCED ===== */
.chat-typing {
  display: flex;
  align-items: center;
  padding: 10px;
  position: relative;
  animation: typing-container-pulse 4s ease-in-out infinite;
}

/* Energy Wave + Sonar */
.chat-typing::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  width: 100%;
  height: 2px;
  background: 
    linear-gradient(90deg, 
      transparent, 
      var(--chat--color-primary), 
      var(--chat--color-secondary),
      transparent
    );
  transform: translateY(-50%) scaleX(0);
  animation: 
    energy-wave 4s ease-in-out infinite,
    sonar-ping 6s ease-out infinite;
  box-shadow: 0 0 10px currentColor;
}

.chat-typing span {
  height: 10px;
  width: 10px;
  margin: 0 4px;
  background-color: var(--chat--color-primary);
  border-radius: 50%;
  opacity: 0.4;
  animation: 
    typing-dots 1.4s infinite, 
    dot-glow 4s infinite,
    dot-morph 6s ease-in-out infinite;
  box-shadow: 
    0 0 8px currentColor,
    0 0 15px currentColor,
    0 0 20px currentColor,
    inset 0 0 5px rgba(255, 255, 255, 0.3);
  position: relative;
  z-index: 1;
}

.chat-typing span:nth-child(2) { 
  animation-delay: 0.2s;
  background: radial-gradient(circle, var(--chat--color-secondary), var(--chat--color-secondary-shade-50));
  box-shadow: 
    0 0 8px var(--chat--color-secondary),
    0 0 15px var(--chat--color-secondary),
    0 0 20px rgba(0, 229, 204, 0.5);
}

.chat-typing span:nth-child(3) { 
  animation-delay: 0.4s;
  background: radial-gradient(circle, var(--chat--color-primary), var(--chat--color-primary-shade-50));
  box-shadow: 
    0 0 8px var(--chat--color-primary),
    0 0 15px var(--chat--color-primary),
    0 0 20px rgba(0, 217, 165, 0.5);
}

/* Particle Emanation */
.chat-typing span::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle, currentColor, transparent);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  animation: 
    particle-emanate 3s infinite,
    ring-expand 4s ease-out infinite;
  opacity: 0;
}

.chat-typing span:nth-child(2)::after { 
  animation-delay: 0.2s;
}

.chat-typing span:nth-child(3)::after { 
  animation-delay: 0.4s;
}

/* ===== FOOTER - ULTRA ENHANCED ===== */
.chat-footer {
  background: 
    linear-gradient(180deg, rgba(0, 217, 165, 0.02), transparent),
    var(--chat--footer--background);
  padding: var(--chat--spacing);
  backdrop-filter: blur(10px) brightness(1.05) saturate(120%);
  -webkit-backdrop-filter: blur(10px) brightness(1.05) saturate(120%);
  z-index: 2;
  border-bottom-left-radius: var(--chat--window--border-radius);
  border-bottom-right-radius: var(--chat--window--border-radius);
  position: relative;
  overflow: hidden;
  animation: footer-breathe 8s ease-in-out infinite;
}

/* Ambient Light + Spectrum */
.chat-footer::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background: 
    linear-gradient(90deg,
      var(--chat--color-primary),
      var(--chat--color-secondary),
      var(--chat--color-primary)
    );
  background-size: 200% 100%;
  animation: 
    ambient-light 6s linear infinite,
    spectrum-shift 10s linear infinite;
  box-shadow: 
    0 0 10px currentColor,
    0 2px 20px currentColor;
}

/* ===== INPUT - MEGA ENHANCED ===== */
.chat-input {
  background-image: 
    radial-gradient(circle at top left, rgba(0, 217, 165, 0.03), transparent),
    linear-gradient(var(--chat--input--background), var(--chat--input--background)),
    linear-gradient(100deg, 
      var(--chat--color-primary), 
      var(--chat--color-secondary),
      var(--chat--color-primary)
    );
  background-origin: border-box;
  background-clip: padding-box, padding-box, border-box;
  border: 2px solid transparent;
  background-size: 100% 100%, 100% 100%, 300% 100%;
  animation: 
    move-border 8s linear infinite,
    input-glow-pulse 6s ease-in-out infinite,
    border-flow 12s linear infinite;
  color: var(--chat--input--text-color);
  height: var(--chat--textarea--height);
  padding: var(--chat--input--padding);
  border-radius: var(--chat--input--border-radius);
  width: 100%;
  transition: all 0.3s ease;
  position: relative;
  box-shadow: 
    0 0 10px rgba(0, 217, 165, 0.15),
    0 0 20px rgba(0, 229, 204, 0.08),
    inset 0 0 10px rgba(0, 0, 0, 0.4),
    inset 0 0 20px rgba(0, 217, 165, 0.01);
}

.chat-input:focus {
  outline: none;
  box-shadow: 
    0 0 25px var(--chat--color-primary), 
    0 0 40px rgba(0, 217, 165, 0.3),
    0 0 60px rgba(0, 229, 204, 0.2),
    0 0 80px rgba(30, 58, 95, 0.15),
    inset 0 0 20px rgba(0, 217, 165, 0.2),
    inset 0 0 30px rgba(0, 229, 204, 0.08);
  animation: 
    input-ripple 1.2s ease-out, 
    move-border 8s linear infinite,
    focus-burst 1s ease-out,
    active-shimmer 4s linear infinite;
  transform: scale(1.005);
}

/* ===== TOGGLE BUTTON - MEGA ENHANCED ===== */
.chat-toggle {
  width: var(--chat--toggle--size);
  height: var(--chat--toggle--size);
  border-radius: var(--chat--toggle--border-radius);
  background: 
    radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.15), transparent),
    var(--chat--toggle--background);
  color: var(--chat--toggle--color);
  box-shadow: 
    0 0 35px rgba(0, 217, 165, 0.5), 
    0 0 45px rgba(0, 229, 204, 0.3),
    0 0 60px rgba(30, 58, 95, 0.2),
    0 0 80px rgba(0, 217, 165, 0.3),
    inset 0 0 20px rgba(255, 255, 255, 0.15),
    inset 0 0 30px rgba(0, 217, 165, 0.08);
  transition: all var(--chat--transition-duration) ease-in-out;
  animation: 
    float 8s infinite ease-in-out, 
    pulse-wave 4s infinite,
    rotate-slow 40s linear infinite,
    color-cycle 12s linear infinite;
  border: 2px solid var(--chat--color-primary);
  position: relative;
  overflow: visible;
  filter: drop-shadow(0 0 10px rgba(0, 217, 165, 0.4));
  font-weight: 700;
}

/* Pulse Wave Rings */
.chat-toggle::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  border: 2px solid var(--chat--color-primary);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  animation: 
    pulse-ring 4s infinite,
    ripple-effect 6s ease-out infinite;
  opacity: 0;
  box-shadow: 0 0 20px currentColor;
}

.chat-toggle::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  border: 2px solid var(--chat--color-secondary);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  animation: 
    pulse-ring 4s infinite 1s,
    ripple-effect 6s ease-out infinite 1s;
  opacity: 0;
  box-shadow: 0 0 20px currentColor;
}

.chat-toggle:hover {
  background: 
    radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.2), transparent),
    var(--chat--toggle--hover--background);
  box-shadow: 
    0 0 55px rgba(0, 229, 204, 0.6), 
    0 0 65px rgba(0, 217, 165, 0.5),
    0 0 90px rgba(30, 58, 95, 0.4),
    0 0 100px rgba(0, 229, 204, 0.3),
    0 0 120px rgba(0, 217, 165, 0.2),
    inset 0 0 30px rgba(255, 255, 255, 0.2),
    inset 0 0 40px rgba(0, 217, 165, 0.15);
  transform: scale(1.15) rotate(-15deg);
  animation: 
    float 8s infinite ease-in-out paused, 
    toggle-burst 1.2s ease-out,
    hover-shake 0.6s ease-in-out,
    supernova-flash 1.6s ease-out;
}

/* ===== SCROLLBAR - ULTRA ENHANCED ===== */
.chat-messages-list::-webkit-scrollbar { 
  width: 10px;
}

.chat-messages-list::-webkit-scrollbar-track { 
  background: 
    linear-gradient(180deg, rgba(0, 217, 165, 0.03), rgba(0, 229, 204, 0.03));
  position: relative;
  border-radius: 10px;
}

.chat-messages-list::-webkit-scrollbar-thumb {
